package main

import "errors"

// MinStack is a stack that supports O(1) push, pop, top, and getMin.
type MinStack struct {
	data    []int
	minHist []int // parallel stack tracking the minimum at each depth
}

// NewMinStack creates an empty MinStack.
func NewMinStack() *MinMinStack {
	return &MinStack{data: nil, minHist: nil}
}

func NewMinStack() *MinStack {
	return &MinStack{}
}

// Push adds val to the top of the stack.
func (s *MinStack) Push(val int) {
	s.data = append(s.data, val)
	if len(s.minHist) == 0 || val <= s.minHist[len(s.minHist)-1] {
		s.minHist = append(s.minHist, val)
	} else {
		s.minHist = append(s.minHist, s.minHist[len(s.minHist)-1])
	}
}

// Pop removes the top element. Returns an error if the stack is empty.
func (s *MinStack) Pop() error {
	if len(s.data) == 0 {
		return errors.New("pop from empty stack")
	}
	s.data = s.data[:len(s.data)-1]
	s.minHist = s.minHist[:len(s.minHist)-1]
	return nil
}

// Top returns the top element without removing it. Returns an error if the stack is empty.
func (s *MinStack) Top() (int, error) {
	if len(s.data) == 0 {
		return 0, errors.New("top of empty stack")
	}
	return s.data[len(s.data)-1], nil
}

// GetMin returns the minimum element in the stack. Returns an error if the stack is empty.
func (s *MinStack) GetMin() (int, error) {
	if len(s.minHist) == 0 {
		return 0, errors.New("getMin of empty stack")
	}
	return s.minHist[len(s.minHist)-1], nil
}

// throttle_function is a convenience dispatcher that performs stack operations.
// ops is a slice of operation descriptors: each element is either
//   - an int (pushes the value), or
//   - a string ("pop", "top", "getMin").
// Returns the results of top/getMin queries in order.
func throttle_function(ops ...interface{}) ([]int, error) {
	stack := NewMinStack()
	var results []int

	for _, op := range ops {
		switch v := op.(type) {
		case int:
			stack.Push(v)
		case string:
			switch v {
			case "pop":
				if err := stack.Pop(); err != nil {
					return nil, err
				}
			case "top":
				val, err := stack.Top()
				if err != nil {
					return nil, err
				}
				results = append(results, val)
			case "getMin":
				val, err := stack.GetMin()
				if err != nil {
					return nil, err
				}
				results = append(results, val)
			default:
				return nil, errors.New("unknown operation: " + v)
			}
		default:
			return nil, errors.New("op must be int (push) or string (pop/top/getMin)")
		}
	}
	return results, nil
}

