5	// MinStack is a stack that supports O(1) push, pop, top, and getMin.
6	type MinStack struct {
7		data    []int
8		minHist []int // parallel stack tracking the minimum at each depth
9	}
10	
11	// NewMinStack creates an empty MinStack.
12	func NewMinStack() *MinStack {
13		return &MinStack{}
14	}
15	
16	// Push adds val to the top of the stack.
17	func (s *MinStack) Push(val int) {
18		s.data = append(s.data, val)
19		if len(s.minHist) == 0 || val <= s.minHist[len(s.minHist)-1] {
20			s.minHist = append(s.minHist, val)
21		} else {
22			s.minHist = append(s.minHist, s.minHist[len(s.minHist)-1])
23		}
24	}
25	
26	// Pop removes the top element. Returns an error if the stack is empty.
27	func (s *MinStack) Pop() error {
28		if len(s.data) == 0 {
29			return errors.New("pop from empty stack")
30		}
31		s.data = s.data[:len(s.data)-1]
32		s.minHist = s.minHist[:len(s.minHist)-1]
33		return nil
34	}
35	
36	// Top returns the top element without removing it. Returns an error if the stack is empty.
37	func (s *MinStack) Top() (int, error) {
38		if len(s.data) == 0 {
39			return 0, errors.New("top of empty stack")
40		}
41		return s.data[len(s.data)-1], nil
42	}
43	
44	// GetMin returns the minimum element in the stack. Returns an error if the stack is empty.
45	func (s *MinStack) GetMin() (int, error) {
46		if len(s.minHist) == 0 {
47			return 0, errors.New("getMin of empty stack")
48		}
49		return s.minHist[len(s.minHist)-1], nil
50	}
51	
52	// throttle_function is a convenience dispatcher that performs stack operations.
53	// ops is a slice of operation descriptors: each element is either
54	//   - an int (pushes the value), or
55	//   - a string ("pop", "top", "getMin").
56	// Returns the results of top/getMin queries in order.
57	func throttle_function(ops ...interface{}) ([]int, error) {
58		stack := NewMinStack()
59		var results []int
60	
61		for _, op := range ops {
62			switch v := op.(type) {
63			case int:
64				stack.Push(v)
65			case string:
66				switch v {
67				case "pop":
68					if err := stack.Pop(); err != nil {
69						return nil, err
70					}
71				case "top":
72					val, err := stack.Top()
73					if err != nil {
74						return nil, err
75					}
76					results = append(results, val)
77				case "getMin":
78					val, err := stack.GetMin()
79					if err != nil {
80						return nil, err
81					}
82					results = append(results, val)
83				default:
84					return nil, errors.New("unknown operation: " + v)
85				}
86			default:
87				return nil, errors.New("op must be int (push) or string (pop/top/getMin)")
88			}
89		}
90		return results, nil
91	}
